(async () => {
  const out = {swipes: document.querySelectorAll('.swipe').length, dots: document.querySelectorAll('.swipe-dots').length,
               docW: document.documentElement.scrollWidth, vw: innerWidth};
  ['#top-picks','#factory'].forEach(s => { const e = document.querySelector(s); out[s] = e ? Math.round(e.offsetHeight) : null; });
  out.doc = document.body.scrollHeight;
  document.querySelector('[data-quote-open]').click();
  await new Promise(r => setTimeout(r, 400));
  const m = document.getElementById('gquote');
  const p = m.querySelector('.gquote__panel');
  const r = p.getBoundingClientRect();
  out.modal = {x: Math.round(r.x), w: Math.round(r.width), overflow: r.right > innerWidth + 1};
  out.pointsClipped = [...m.querySelectorAll('.gquote__points li')].map(li => li.scrollWidth > li.clientWidth + 1);
  return out;
})()
